// Images fixes des passes Wallet — embarquées en base64 (le bundler edge ne
// suit pas les fichiers statiques). Deux images seulement : l'icône de l'app
// (verre yuno sur rouge) et le wordmark blanc « yuno ». L'affiche de la soirée,
// elle, est produite par pass dans artwork.ts.
//
// Contraintes Apple qui pilotent ces images, ne pas les défaire :
//  - icon 29x29pt : c'est ce que Wallet montre dans la liste des passes, dans
//    les notifications et sur l'écran verrouillé. Elle DOIT être l'icône de
//    l'app, pas un glyphe abstrait — un pass qu'on ne reconnaît pas dans une
//    liste de dix est un pass qu'on ne sort pas à la porte.
//  - logo 160x50 .. 480x150 : c'est le PLAFOND Apple. Un wordmark qui remplit
//    le cadre rend donc au maximum absolu. Le cadre reste 160x50 pour que
//    l'en-tête garde sa hauteur, mais le wordmark n'y occupe que ~72pt de
//    large, calé à gauche, le reste transparent.
//
// Il n'y a PLUS de background.png : le design 2026-09 pose un noir plein
// (`backgroundColor`), et Wallet ne sait pas faire de dégradé. L'ancienne rampe
// noir → rouge était une image étirée qui noyait le QR et faisait tomber le
// contraste des labels sous le seuil AA dans le bas du pass.
//
// Régénérer via : python3 scripts/gen-wallet-assets.py

function b64(data: string): Uint8Array {
  const bin = atob(data);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

