/** Images du pass, prêtes pour buildPkpass(). */
export function walletAssets(): Record<string, Uint8Array> {
  return {
    'icon.png': b64(ICON),
    'icon@2x.png': b64(ICON2X),
    'icon@3x.png': b64(ICON3X),
    // eventTicket classique (iOS 17−) : le wordmark dans son cadre 160x50.
    'logo.png': b64(LOGO),
    'logo@2x.png': b64(LOGO2X),
    'logo@3x.png': b64(LOGO3X),
    // Poster event ticket (iOS 18+) : le même wordmark, détouré au ras.
    'primaryLogo.png': b64(PLOGO),
    'primaryLogo@2x.png': b64(PLOGO2X),
    'primaryLogo@3x.png': b64(PLOGO3X),
  };
}
